begin;
create table catalog.categories(catalog_id uuid not null references catalog.catalogs(id) on delete cascade,path text not null check(length(path) between 1 and 1000),primary key(catalog_id,path));
create table catalog.book_relations(catalog_id uuid not null,book_id uuid not null,related_book_id uuid not null,kind text not null check(kind in ('same_work','sample_of')),source text not null default 'manual',primary key(catalog_id,book_id,related_book_id,kind),check(book_id<>related_book_id),foreign key(catalog_id,book_id) references catalog.books(catalog_id,id) on delete cascade,foreign key(catalog_id,related_book_id) references catalog.books(catalog_id,id) on delete cascade);
create table catalog.book_covers(catalog_id uuid not null,book_id uuid primary key,content bytea not null check(octet_length(content)<=524288),foreign key(catalog_id,book_id) references catalog.books(catalog_id,id) on delete cascade);
create table catalog.sync_devices(id uuid primary key,user_id text not null references catalog.users(id),catalog_id uuid not null references catalog.catalogs(id) on delete cascade,name text not null,token_hash text unique not null,expires_at timestamptz not null,revoked_at timestamptz,created_at timestamptz not null default now());
create table catalog.sync_pairings(id uuid primary key default gen_random_uuid(),device_id uuid not null,device_name text not null,challenge text not null,user_code text not null,expires_at timestamptz not null default(now()+interval '10 minutes'),user_id text references catalog.users(id),catalog_id uuid references catalog.catalogs(id) on delete cascade,approved_at timestamptz,consumed_at timestamptz);
create index sync_pairings_expiry on catalog.sync_pairings(expires_at);
alter table catalog.sync_links add column payload_hash text not null default '';
create table catalog.sync_batches(device_id uuid not null references catalog.sync_devices(id) on delete cascade,request_id uuid not null,payload_hash text not null,response jsonb not null,created_at timestamptz not null default now(),primary key(device_id,request_id));
create table catalog.sync_events(seq bigint generated always as identity primary key,catalog_id uuid not null references catalog.catalogs(id) on delete cascade,book_id uuid not null,comment_id uuid references catalog.comments(id) on delete cascade,kind text not null check(kind in ('book','comment')),foreign key(catalog_id,book_id) references catalog.books(catalog_id,id) on delete cascade);
create index sync_events_catalog on catalog.sync_events(catalog_id,seq);
alter table catalog.comments add column origin text not null default 'web' check(origin in ('web','desktop'));
create table catalog.sync_annotations(catalog_id uuid not null,device_id uuid not null references catalog.sync_devices(id) on delete cascade,local_id text not null,comment_id uuid not null references catalog.comments(id) on delete cascade,primary key(catalog_id,device_id,local_id));
create function catalog.record_book_event()returns trigger language plpgsql as $$begin insert into catalog.sync_events(catalog_id,book_id,kind)values(NEW.catalog_id,NEW.id,'book');return NEW;end$$;
create trigger sync_book_changes after insert or update on catalog.books for each row execute function catalog.record_book_event();
create function catalog.record_comment_event()returns trigger language plpgsql as $$begin insert into catalog.sync_events(catalog_id,book_id,comment_id,kind)values(NEW.catalog_id,NEW.book_id,NEW.id,'comment');return NEW;end$$;
create trigger sync_comment_changes after insert on catalog.comments for each row execute function catalog.record_comment_event();
insert into catalog.sync_events(catalog_id,book_id,kind)select catalog_id,id,'book'from catalog.books;
insert into catalog.sync_events(catalog_id,book_id,comment_id,kind)select catalog_id,book_id,id,'comment'from catalog.comments;
alter table catalog.privacy_requests add column completed_at timestamptz;
alter table catalog.privacy_requests add column handled_by text references catalog.users(id);
create table catalog.erased_accounts(user_id text primary key,erased_at timestamptz not null default now());
alter table catalog.categories enable row level security;
alter table catalog.book_relations enable row level security;
alter table catalog.book_covers enable row level security;
alter table catalog.sync_devices enable row level security;
alter table catalog.sync_pairings enable row level security;
alter table catalog.sync_batches enable row level security;
alter table catalog.sync_events enable row level security;
alter table catalog.sync_annotations enable row level security;
alter table catalog.erased_accounts enable row level security;
revoke all on all tables in schema catalog from public,anon,authenticated;
commit;
